"""Qualification explanation and a non-saving preview inside the lead editor."""

# ruff: noqa: E501 - embedded dashboard script.

QUALIFICATION_SCRIPT = r"""<script>
const reviewOnly=__REVIEW_ONLY__,baseOpenEditor=openEditor;
let qualificationSerial=0,qualificationTimer=null;
function reviewPayload(){const p=Object.fromEntries(new FormData(document.getElementById('editForm')));p.funds_gbp=p.funds_gbp?Number(p.funds_gbp):null;return p;}
function renderQualification(data){const box=document.getElementById('qualificationSummary');if(!box)return;box.replaceChildren();const heading=document.createElement('h3');heading.textContent=`Qualification: ${data.score}/100 · threshold ${data.minimum_score}`;heading.style.margin='0 0 8px';const campaign=document.createElement('p');campaign.textContent='Campaign: '+data.campaign+' · Uses the rules saved with this research run.';box.append(heading,campaign);const grid=document.createElement('div');grid.style.cssText='display:grid;grid-template-columns:1fr 1fr;gap:8px';for(const part of data.components){const item=document.createElement('div');item.textContent=`${part.label}: +${part.points} — ${part.evidence}`;grid.append(item)}box.append(grid);const result=document.createElement('p');result.style.fontWeight='700';result.style.color=data.can_approve?'#087a4d':'#985c00';result.textContent=data.can_approve?'Eligible for your review decision. Approval does not send anything.':'Before approval: '+data.blockers.join('; ');box.append(result);const evidence=document.createElement('div');evidence.textContent='Matching criteria: '+(data.matched_criteria.join(', ')||'None recorded')+'. Missing profile data: '+(data.missing_fields.join(', ')||'None in tracked fields')+'.';const note=document.createElement('p');note.className='sub';note.textContent=data.require_fund_evidence?`Funds evidence required: at least GBP ${data.minimum_funds_gbp.toLocaleString()}. The source is entered by the reviewer; this app does not independently verify it.`:'Funds evidence is optional for this campaign. Any supplied source must be checked by the reviewer.';box.append(evidence,note);document.getElementById('saveResult').textContent='Draft changes are saved only when you click Save client.';}
async function previewQualification(){if(!editing||!editor.open)return;const serial=++qualificationSerial,id=editing.lead.id;try{const r=await fetch(`/api/leads/${id}/qualification`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(reviewPayload())});const data=await r.json();if(serial!==qualificationSerial||editing?.lead.id!==id||!editor.open)return;if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Check the review fields');renderQualification(data);}catch(e){if(serial===qualificationSerial){const box=document.getElementById('qualificationSummary');if(box)box.textContent='Could not preview qualification: '+e.message;}}}
openEditor=async function(id){clearTimeout(qualificationTimer);const serial=++qualificationSerial;baseOpenEditor(id);const form=document.getElementById('editForm');for(const el of form.querySelectorAll('[name]')){el.id='review-'+el.name;const label=el.parentElement.querySelector('label');if(label)label.htmlFor=el.id;}const status=form.elements.namedItem('status');if(reviewOnly){const current=status.value;status.replaceChildren();for(const s of ['needs_verification','ready_for_review','approved','rejected'])status.add(new Option(label(s),s,false,current===s));}const box=document.createElement('div');box.id='qualificationSummary';box.className='field full profile-value';box.style.maxHeight='none';box.setAttribute('role','status');box.textContent='Loading qualification evidence…';document.getElementById('formGrid').prepend(box);try{const r=await fetch(`/api/leads/${id}/qualification`);const data=await r.json();if(serial!==qualificationSerial||editing?.lead.id!==id||!editor.open)return;if(!r.ok)throw Error('Could not load qualification');const firm=form.elements.namedItem('firm_type'),select=document.createElement('select');select.name=firm.name;select.id=firm.id;select.add(new Option('Not confirmed',''));for(const value of data.firm_types)select.add(new Option(value,value));if(firm.value&&!data.firm_types.includes(firm.value))select.add(new Option(firm.value+' (outside campaign)',firm.value));select.value=firm.value;firm.replaceWith(select);renderQualification(data);}catch(e){if(serial===qualificationSerial)box.textContent=e.message;}};
document.getElementById('editForm').addEventListener('input',()=>{clearTimeout(qualificationTimer);qualificationTimer=setTimeout(previewQualification,350);});
document.getElementById('editForm').onsubmit=async e=>{e.preventDefault();clearTimeout(qualificationTimer);const id=editing.lead.id,button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{const r=await fetch(`/api/leads/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(reviewPayload())});const body=await r.json();if(!r.ok){const error=typeof body.detail==='string'?body.detail:'Check the review fields';document.getElementById('saveResult').textContent=error;notice(error);await previewQualification();return;}++qualificationSerial;editor.close();notice('Review saved. No outreach was sent.');await Promise.all([load(),loadSummary()]);}catch(e){document.getElementById('saveResult').textContent='Could not save. Check connection and retry.';}finally{button.disabled=false;}};
</script>"""
